//This is a async fifo generated by claude assumed to be a golden model
//I cannot guarantee the correctness of the code.

module gold_top #(
  parameter DW = 8,
  parameter AW = 4                    // depth = 2^AW (AW=4 -> 16 deep)
)(
  // write domain
  input  logic          w_clk,
  input  logic          wrst_n,
  input  logic          w_en,
  input  logic [DW-1:0] data_in,
  output logic          full,
  // read domain
  input  logic          r_clk,
  input  logic          rrst_n,
  input  logic          r_en,
  output logic [DW-1:0] data_out,
  output logic          empty,
  // exposed for the checker (physical addresses into mem)
  output logic [AW-1:0] w_ptr,        // binary write address (mem index)
  output logic [AW-1:0] r_ptr         // binary read  address (mem index)
);

  // ---- memory ----------------------------------------------------------------
  logic [DW-1:0] mem [0:(1<<AW)-1];

  // ---- write-domain pointers -------------------------------------------------
  logic [AW:0] wbin, wgray, wbin_next, wgray_next;   // AW+1 bits (extra wrap bit)
  logic [AW:0] rgray_sync;                            // read gray, synced to w

  assign wbin_next  = wbin + (w_en & ~full);
  assign wgray_next = (wbin_next >> 1) ^ wbin_next;

  always_ff @(posedge w_clk or negedge wrst_n)
    if (!wrst_n) begin wbin <= '0; wgray <= '0; end
    else         begin wbin <= wbin_next; wgray <= wgray_next; end

  assign w_ptr = wbin[AW-1:0];        // physical index (drop wrap bit)

  // memory write (registered) ? data lands same edge pointer advances
  always_ff @(posedge w_clk)
    if (w_en & ~full) mem[w_ptr] <= data_in;

  // ---- read-domain pointers --------------------------------------------------
  logic [AW:0] rbin, rgray, rbin_next, rgray_next;
  logic [AW:0] wgray_sync;                            // write gray, synced to r

  assign rbin_next  = rbin + (r_en & ~empty);
  assign rgray_next = (rbin_next >> 1) ^ rbin_next;

  always_ff @(posedge r_clk or negedge rrst_n)
    if (!rrst_n) begin rbin <= '0; rgray <= '0; end
    else         begin rbin <= rbin_next; rgray <= rgray_next; end

  assign r_ptr = rbin[AW-1:0];

  // registered read data  -> checker must use |=>
  always_ff @(posedge r_clk)
    if (r_en & ~empty) data_out <= mem[r_ptr];

  // ---- 2-flop synchronizers --------------------------------------------------
  logic [AW:0] wq1, rq1;
  always_ff @(posedge r_clk or negedge rrst_n)      // write gray -> read domain
    if (!rrst_n) begin wq1 <= '0; wgray_sync <= '0; end
    else         begin wq1 <= wgray; wgray_sync <= wq1; end

  always_ff @(posedge w_clk or negedge wrst_n)      // read gray -> write domain
    if (!wrst_n) begin rq1 <= '0; rgray_sync <= '0; end
    else         begin rq1 <= rgray; rgray_sync <= rq1; end

  // ---- flags -----------------------------------------------------------------
  // empty: read gray caught up to synced write gray
  always_ff @(posedge r_clk or negedge rrst_n)
    if (!rrst_n) empty <= 1'b1;
    else         empty <= (rgray_next == wgray_sync);

  // full: write gray_next equals synced read gray with top two bits inverted
  always_ff @(posedge w_clk or negedge wrst_n)
    if (!wrst_n) full <= 1'b0;
    else         full <= (wgray_next ==
                          {~rgray_sync[AW:AW-1], rgray_sync[AW-2:0]});

endmodule
